(()=>{'use strict';
const V='20260904-wb2025s2-dia1-v1';
const CURRENT_TEAMS=['AFROGAMES','ALPHA7','CIVIS','CPT VOX','FLUXO W7M','INFLUENCE RAGE','INTZ','LOOPS','LOS','LOUD SNICKERS','RISE GAMING','RUSH GAMING','SX TET','TEAM SOLID'];
const LOCAL_LOGOS={'AFROGAMES':'afg.webp','CPT VOX':'cpt vox.webp','SX TET':'sx tet.webp'};
const overlay=document.getElementById('cff-public-overlay'),sidebar=document.getElementById('cff-public-sidebar'),nav=document.getElementById('cff-public-sidebar-nav'),openBtn=document.getElementById('cff-public-menu-open'),closeBtn=document.getElementById('cff-public-menu-close');
const teamsBtn=document.getElementById('cff-public-teams-toggle'),teamsDrop=document.getElementById('cff-public-teams-dropdown'),teamsGrid=document.getElementById('cff-public-teams-grid');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9]+/g,'');
const section=(key,title,links,open=false)=>`<section class="cff-public-sidebar-section${open?' is-open':''}" data-section-key="${key}"><button class="cff-public-sidebar-section-toggle" type="button" data-cff-section="${key}" aria-expanded="${open?'true':'false'}"><span>${title}</span><span class="cff-public-sidebar-chevron" aria-hidden="true">⌄</span></button><div class="cff-public-sidebar-section-content"><div>${links.map(([label,href])=>`<a href="${href}">${label}</a>`).join('')}</div></div></section>`;
const divider='<div class="cff-public-sidebar-divider"></div>';
const menu=`<div class="cff-public-sidebar-category">PRINCIPAL</div>
<a href="index.html">INÍCIO</a><a href="index.html#mercado">MERCADO DA BALA</a><a href="tier-constructor.html">TIER CONSTRUCTOR</a><a href="manager.html?v=20260610-wb-standalone-v2">WB MANAGER BETA</a>${divider}
${section('ffws-br-s2','WB 2026 S2',[
['CLASSIFICATÓRIA','index.html#ffws-br-s2-classificatoria'],['SEGUNDA FASE','index.html#ffws-br-s2-segunda-fase'],['FINAL','index.html#ffws-br-s2-final'],['RANKING MVP','index.html#ffws-br-s2-mvp'],['EQUIPES','index.html#ffws-br-s2-equipes'],['DATAS','index.html#ffws-br-s2-datas'],['SELEÇÕES DA SEASON','index.html#ffws-br-s2-selecoes'],['ESTATÍSTICAS GERAIS','index.html#ffws-br-s2-stats'],['NOTAS CFF','index.html#ffws-br-s2-notas'],['COMPARAR 1V1','index.html#ffws-br-s2-comparar']],true)}${divider}
${section('oficiais','TORNEIOS OFICIAIS',[
['EWC 2026 • FASE DE GRUPOS','index.html#ewc-grupos'],['EWC 2026 • REPESCAGEM','index.html#ewc-repescagem'],['EWC 2026 • FINAL','index.html#ewc-final'],['EWC 2026 • RANKING MVP','index.html#ewc-mvp'],['EWC 2026 • EQUIPES','index.html#ewc-equipes'],['EWC 2026 • ESTATÍSTICAS GERAIS','index.html#ewc-stats'],
['WB 2026 S1 • CLASSIFICATÓRIA','index.html#tabela'],['WB 2026 S1 • FINAL','index.html#final'],['WB 2026 S1 • RANKING MVP','index.html#mvp'],['WB 2026 S1 • EQUIPES','index.html#equipes'],['WB 2026 S1 • DATAS','index.html#datas'],['WB 2026 S1 • SELEÇÕES DA SEASON','index.html#selecao-da-semana'],['WB 2026 S1 • ESTATÍSTICAS GERAIS','index.html#stats'],['WB 2026 S1 • NOTAS CFF','index.html#notas-cff'],['WB 2026 S1 • COMPARAR 1V1','index.html#comparar-1v1'],
['LAFF 2026 S1 • CLASSIFICATÓRIA','index.html#laff-classificatoria'],['LAFF 2026 S1 • RANKING MVP','index.html#laff-mvp'],['LAFF 2026 S1 • EQUIPES','index.html#laff-equipes'],['LAFF 2026 S1 • DATAS','index.html#laff-datas'],['LAFF 2026 S1 • SELEÇÕES DA SEASON','index.html#laff-selecoes'],['LAFF 2026 S1 • ESTATÍSTICAS GERAIS','index.html#laff-stats'],
['WB 2025 S2 • CLASSIFICATÓRIA','index.html#ffws-br-2025-s2-classificatoria'],['WB 2025 S2 • CONTRA SQUAD','index.html#ffws-br-2025-s2-contra-squad'],['WB 2025 S2 • FINAL','index.html#ffws-br-2025-s2-final'],['WB 2025 S2 • RANKING MVP','index.html#ffws-br-2025-s2-mvp'],['WB 2025 S2 • EQUIPES','index.html#ffws-br-2025-s2-equipes'],['WB 2025 S2 • DATAS','index.html#ffws-br-2025-s2-datas'],['WB 2025 S2 • SELEÇÕES DA SEASON','index.html#ffws-br-2025-s2-selecoes'],['WB 2025 S2 • ESTATÍSTICAS GERAIS','index.html#ffws-br-2025-s2-stats'],['WB 2025 S2 • NOTAS CFF','index.html#ffws-br-2025-s2-notas'],['WB 2025 S2 • COMPARAR 1V1','index.html#ffws-br-2025-s2-comparar']])}${divider}
${section('internacional','INTERNACIONAL',[
['FFWS SEA 2026 S1','index.html#ffws-sea-2026-s1'],['FFWS LATAM S1','index.html#ffws-latam-s1']])}${divider}
${section('historico','HISTÓRICO',[
['HALL DA FAMA','index.html#hall-da-fama'],['REGISTRO DETALHADO','index.html#registro-detalhado'],['OUTROS TORNEIOS','index.html#outros-torneios'],['EQUIPES HISTÓRICAS','equipes-historicas.html'],['OUTRAS EQUIPES','index.html#outras-equipes']])}${divider}
${section('contato','CONTATO', [['SOBRE','index.html#sobre']])}${divider}
<div class="cff-public-sidebar-category">SISTEMA</div><button type="button" id="cff-public-refresh">ATUALIZAR DADOS</button>`;
let built=false;
function build(){if(built||!nav)return;nav.innerHTML=menu;built=true;nav.querySelectorAll('[data-cff-section]').forEach(btn=>btn.addEventListener('click',()=>{const sec=btn.closest('.cff-public-sidebar-section');if(!sec)return;const open=!sec.classList.contains('is-open');sec.classList.toggle('is-open',open);btn.setAttribute('aria-expanded',String(open))}));nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',close));nav.querySelector('#cff-public-refresh')?.addEventListener('click',()=>location.reload())}
function open(){build();overlay?.classList.add('is-open');sidebar?.classList.add('is-open');document.body.classList.add('cff-public-menu-open');closeBtn?.focus()}
function close(){overlay?.classList.remove('is-open');sidebar?.classList.remove('is-open');document.body.classList.remove('cff-public-menu-open')}
openBtn?.addEventListener('click',open);closeBtn?.addEventListener('click',close);overlay?.addEventListener('click',close);document.addEventListener('keydown',e=>{if(e.key==='Escape'){close();closeTeams()}});

let logoData=null;
function findLogo(name){if(LOCAL_LOGOS[name])return LOCAL_LOGOS[name];if(!logoData)return'escudo.webp';const target=Object.entries(logoData.aliases||{}).find(([k])=>norm(k)===norm(name))?.[1]||name;return Object.entries(logoData.logos||{}).find(([k])=>norm(k)===norm(target))?.[1]||'escudo.webp'}
function teamUrl(name){return`equipe.html?time=${encodeURIComponent(name)}`}
function renderTeams(){if(!teamsGrid)return;teamsGrid.innerHTML=CURRENT_TEAMS.map(name=>`<button class="cff-public-team-btn" type="button" aria-label="${esc(name)}" data-team="${esc(name)}"><img src="${esc(findLogo(name))}" alt="${esc(name)}" loading="lazy" decoding="async" onerror="this.onerror=null;this.src='escudo.webp'"></button>`).join('');teamsGrid.querySelectorAll('[data-team]').forEach(btn=>btn.addEventListener('click',()=>{location.href=teamUrl(btn.dataset.team||'')}))}
function ensureTeams(){if(logoData){renderTeams();return Promise.resolve()}return fetch(`team-data/logo-map.json?v=${V}`,{cache:'default'}).then(r=>r.ok?r.json():Promise.reject()).then(d=>{logoData=d||{logos:{},aliases:{}}}).catch(()=>{logoData={logos:{},aliases:{}}}).finally(renderTeams)}
function closeTeams(){teamsDrop?.classList.remove('is-open');teamsBtn?.setAttribute('aria-expanded','false')}
function toggleTeams(e){e?.stopPropagation();const next=!teamsDrop?.classList.contains('is-open');closeTeams();if(next){ensureTeams();teamsDrop?.classList.add('is-open');teamsBtn?.setAttribute('aria-expanded','true')}}
teamsBtn?.addEventListener('click',toggleTeams);document.addEventListener('click',e=>{if(!e.target.closest('.cff-public-teams'))closeTeams()});

const input=document.getElementById('cff-public-search-input'),results=document.getElementById('cff-public-search-results'),submit=document.getElementById('cff-public-search-submit');let items=[],loading=null,timer=0;
const normSearch=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim();
function load(){if(items.length)return Promise.resolve(items);if(loading)return loading;loading=fetch(`search-index-lite.json?v=${V}`,{cache:'default'}).then(r=>r.ok?r.json():Promise.reject()).then(d=>{items=(d.items||[]).filter(x=>x&&x.title&&x.title!=='#N/A').map(x=>({...x,_q:normSearch([x.title,x.sub,...(x.aliases||[])].join(' ')),_t:normSearch(x.title)}));return items}).catch(()=>[]);return loading}
function searchUrl(x){if(x.type==='player')return`jogador.html?id=${encodeURIComponent(x.id)}`;if(x.type==='team')return teamUrl(x.title||x.id);return x.url||`index.html#${encodeURIComponent(x.id||'home')}`}
function score(x,q,tokens){if(x._t===q)return 1000;if(x._t.startsWith(q))return 850;if(x._q.startsWith(q))return 760;if(x._q.includes(q))return 620;let n=0;for(const t of tokens)if(x._q.includes(t))n++;return n===tokens.length?420+n*10:-1}
function render(q){q=normSearch(q);if(!results)return;if(!q){results.classList.remove('is-open');results.innerHTML='';return}const tokens=q.split(' ').filter(Boolean),found=items.map(x=>({x,s:score(x,q,tokens)})).filter(v=>v.s>=0).sort((a,b)=>b.s-a.s||a.x.title.localeCompare(b.x.title,'pt-BR')).slice(0,10).map(v=>v.x);results.innerHTML=found.length?found.map(x=>`<a class="cff-public-search-item" href="${searchUrl(x)}"><img src="${esc(x.image||'central free fire.webp')}" alt="" loading="lazy" decoding="async" onerror="this.onerror=null;this.src='silhueta.webp'"><span class="cff-public-search-copy"><strong>${esc(x.title)}</strong><small>${esc(x.sub||'')}</small></span></a>`).join(''):'<div class="cff-public-search-empty">Nenhum resultado encontrado.</div>';results.classList.add('is-open')}
function requestRender(){clearTimeout(timer);timer=setTimeout(async()=>{await load();render(input?.value)},45)}
input?.addEventListener('focus',()=>{load();if(input.value)requestRender()});input?.addEventListener('input',requestRender);input?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();const first=results?.querySelector('a');if(first)location.href=first.href;else location.href=`index.html#busca-global?q=${encodeURIComponent(input.value)}`}});submit?.addEventListener('click',()=>{input?.focus();requestRender()});document.addEventListener('click',e=>{if(!e.target.closest('.cff-public-search'))results?.classList.remove('is-open')});
})();
